ee:variables.ee:set-variable:
%dw 2.0
output application/java
---
(vars.compareRequest.propertyCodes default []) map ((c) -> do {
	var single = ((vars.singleResults default []) filter ((r) -> r.code == c))[0]
	var hit = ((vars.batchList default []) filter ((e) -> ((e.propertyCode default '') as String) == c))[0]
	---
	single default {code: c, status: "ok", source: "batch", property: hit}
})

%dw 2.0
output application/json
---
(vars.propertyInfoRequest default {}) mapObject ((v, k) ->
	if ((k as String) == "propertyListing") {(k): true}
	else if ((k as String) == "propertyCode") {(k): vars.batchCodes default []}
	else {(k): v})
